"""Track the filenames actually generated by QGIS layout export."""
import os

from qgis.core import QgsLayoutExporter


class ArtifactLayoutExporter(QgsLayoutExporter):
    def __init__(self, layout):
        super().__init__(layout)
        self.page_paths = []

    def generateFileName(self, details):
        path = super().generateFileName(details)
        self.page_paths.append(path)
        return path

    def artifact_paths(self, fallback):
        paths = list(dict.fromkeys(self.page_paths or [fallback]))
        if not paths or any(not os.path.isfile(path) for path in paths):
            raise ValueError("导出未生成完整文件，无法登记成果")
        return [os.path.abspath(path) for path in paths]
